ALTER TABLE "SafetyReport" ADD COLUMN "assignedAdministratorId" TEXT, ADD COLUMN "assignedAt" TIMESTAMPTZ(3);
CREATE TABLE "SafetyReportAssignmentEvent" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"safetyReportId" UUID NOT NULL,"actingAdministratorId" TEXT NOT NULL,"previousAssignedAdministratorId" TEXT,"newAssignedAdministratorId" TEXT,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SafetyReportAssignmentEvent_pkey" PRIMARY KEY ("id"),CONSTRAINT "SafetyReportAssignmentEvent_change_check" CHECK ("previousAssignedAdministratorId" IS DISTINCT FROM "newAssignedAdministratorId"));
CREATE TABLE "SafetyReportInternalNote" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"safetyReportId" UUID NOT NULL,"administratorId" TEXT NOT NULL,"body" VARCHAR(2000) NOT NULL,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SafetyReportInternalNote_pkey" PRIMARY KEY ("id"),CONSTRAINT "SafetyReportInternalNote_body_check" CHECK ("body" = btrim("body") AND char_length("body") BETWEEN 1 AND 2000));
CREATE INDEX "SafetyReportAssignmentEvent_safetyReportId_createdAt_id_idx" ON "SafetyReportAssignmentEvent"("safetyReportId","createdAt","id");CREATE INDEX "SafetyReportInternalNote_safetyReportId_createdAt_id_idx" ON "SafetyReportInternalNote"("safetyReportId","createdAt","id");
ALTER TABLE "SafetyReport" ADD CONSTRAINT "SafetyReport_assignedAdministratorId_fkey" FOREIGN KEY ("assignedAdministratorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SafetyReportAssignmentEvent" ADD CONSTRAINT "SafetyReportAssignmentEvent_safetyReportId_fkey" FOREIGN KEY ("safetyReportId") REFERENCES "SafetyReport"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "SafetyReportAssignmentEvent" ADD CONSTRAINT "SafetyReportAssignmentEvent_actingAdministratorId_fkey" FOREIGN KEY ("actingAdministratorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "SafetyReportAssignmentEvent" ADD CONSTRAINT "SafetyReportAssignmentEvent_previousAssignedAdministratorId_fkey" FOREIGN KEY ("previousAssignedAdministratorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "SafetyReportAssignmentEvent" ADD CONSTRAINT "SafetyReportAssignmentEvent_newAssignedAdministratorId_fkey" FOREIGN KEY ("newAssignedAdministratorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SafetyReportInternalNote" ADD CONSTRAINT "SafetyReportInternalNote_safetyReportId_fkey" FOREIGN KEY ("safetyReportId") REFERENCES "SafetyReport"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "SafetyReportInternalNote" ADD CONSTRAINT "SafetyReportInternalNote_administratorId_fkey" FOREIGN KEY ("administratorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
